using CatalogService.Endpoints;using CatalogService.Services;using Microsoft.OpenApi.Models;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="WAEC Catalog Service API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});builder.Services.AddSingleton<SubjectStore>();var app=builder.Build();app.UseSwagger();app.UseSwaggerUI(o=>{o.SwaggerEndpoint("/swagger/v1/swagger.json","WAEC Catalog Service API V1");o.RoutePrefix="swagger";});app.MapCatalogEndpoints();app.Run();